    private static Vocabulary v(String word, String ipaUk, String ipaUs, String type, String vi, String contextMeaningVi, String exEn, String exVi, String collocations, String commonMistake, String level, String topic) {
        Vocabulary vocab = new Vocabulary();
        vocab.setWord(word);
        vocab.setIpaUk(ipaUk);
        vocab.setIpaUs(ipaUs);
        vocab.setType(type);
        vocab.setMeaningVi(vi);
        vocab.setContextMeaningVi(contextMeaningVi);
        vocab.setExampleEn(exEn);
        vocab.setExampleVi(exVi);
        vocab.setCollocations(collocations);
        vocab.setCommonMistake(commonMistake);
        vocab.setLevel(level);
        vocab.setTopic(topic);
        vocab.setMasteryLevel(0);
        vocab.setFavorite(false);
        return vocab;
    }
